import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between start and end nodes.

    Args:
        edges: List of (from_node, to_node, weight) tuples
        start: Starting node (string or hashable)
        end: Ending node (string or hashable)

    Returns:
        (distance, path) tuple where distance is the shortest total weight
        and path is a list of nodes from start to end.

    Raises:
        ValueError: If any edge has a negative weight

    Returns:
        (None, None): If no path exists or nodes are not in graph
    """
    # Check for negative edge weights first
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight is not allowed")

    # Handle case where start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list graph
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Check if start node exists in graph
    if start not in graph:
        return (None, None)

    # Dijkstra's algorithm with priority queue
    distances = {start: 0}
    previous = {start: None}
    pq = [(0, start)]  # (distance, node)

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        # Skip if we've already found a shorter path to this node
        if current_dist > distances.get(current_node, float('inf')):
            continue

        # If we reached the destination, break early
        if current_node == end:
            break

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance = current_dist + weight

                # Only update if we found a shorter path
                if distance < distances.get(neighbor, float('inf')):
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(pq, (distance, neighbor))

    # Check if end is reachable
    if end not in distances:
        return (None, None)

    # Reconstruct path from end to start using previous node tracking
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous.get(current)

    path.reverse()

    return (distances[end], path)
